def cls_decorator_helper(cls: _T) -> _T:
    # helper to pass `dynamic_arg_dims`` to `_support_torch_compile``
    # to avoid too much indentation for `_support_torch_compile``
    if not hasattr(cls, 'forward'):
        raise TypeError("decorated class should have a forward method.")
    sig = inspect.signature(cls.forward)
    inferred_dynamic_arg_dims = dynamic_arg_dims
    if inferred_dynamic_arg_dims is None:
        inferred_dynamic_arg_dims = {}
        for k, v in sig.parameters.items():
            if v.annotation in [
                    torch.Tensor, Optional[torch.Tensor],
                    IntermediateTensors, Optional[IntermediateTensors]
            ]:
                inferred_dynamic_arg_dims[k] = 0

        logger.debug(("Inferred dynamic dimensions for "
                      "forward method of %s: %s"), cls,
                     list(inferred_dynamic_arg_dims.keys()))

    if len(inferred_dynamic_arg_dims) == 0:
        raise ValueError(
            "No dynamic dimensions found in the forward method of "
            f"{cls}. Please provide dynamic_arg_dims explicitly.")

    for k in inferred_dynamic_arg_dims:
        if k not in sig.parameters:
            raise ValueError(
                f"Argument {k} not found in the forward method of {cls}")
    return _support_torch_compile(cls, inferred_dynamic_arg_dims)

if cls is not None:
    # use `support_torch_compile` as a decorator without arguments
    assert isinstance(cls, type)
    return cls_decorator_helper(cls)

return cls_decorator_helper

class Pooler(nn.Module, ABC):
    """The interface required for all poolers used in pooling models in vLLM."""

    @staticmethod
    def for_encode(pooler_config: PoolerConfig):
        if pooler_config.pooling_type == "STEP":
            return StepPooler()

        resolved_config = ResolvedPoolingConfig(task="encode",
                                                pooling_type=PoolingType.ALL)

        return SimplePooler.from_config(resolved_config)

    @staticmethod
    def for_embed(pooler_config: PoolerConfig):
        resolved_config = ResolvedPoolingConfig.from_config(
            task="embed",
            pooler_config=pooler_config,
        )

        return SimplePooler.from_config(resolved_config)

    @staticmethod
    def for_classify(
        pooler_config: PoolerConfig,
        classifier: Optional[ClassifierFn],
    ):
        resolved_config = ResolvedPoolingConfig.from_config(
            task="classify",
            pooler_config=pooler_config,
        )

        pooling = PoolingMethod.from_pooling_type(resolved_config.pooling_type)

        return ClassifierPooler(
            pooling=pooling,
            classifier=classifier,
        )

    @abstractmethod
    def get_supported_tasks(self) -> Set[PoolingTask]:
        """Determine which pooling tasks are supported."""
        raise NotImplementedError

    def get_pooling_updates(self, task: PoolingTask) -> PoolingParamsUpdate:
        """
        Construct the updated pooling parameters to use for a supported task.
        """
        return PoolingParamsUpdate()

    @abstractmethod
    def forward(
        self,
        hidden_states: Union[list[torch.Tensor], torch.Tensor],
        pooling_metadata: PoolingMetadata,
    ) -> PoolerOutput:
        raise NotImplementedError

    intermediate_tensors: Optional[IntermediateTensors] = None,
    inputs_embeds: Optional[torch.Tensor] = None,
) -> Union[torch.Tensor, IntermediateTensors]:
    hidden_states = self.model(input_ids, positions, intermediate_tensors,
                               inputs_embeds)
    return hidden_states

